#Requires -Version 5.1
<#
.SYNOPSIS
Creates a bootable USB drive for Windows Autopilot hardware hash extraction from WinPE.
.DESCRIPTION
A self-contained PowerShell Windows Forms GUI tool that prepares a USB drive with
WinPE boot files, Autopilot hash extraction tools (oa3tool.exe, PCPKsp.dll), and
embedded helper scripts. The required binaries are embedded as base64 and decoded
at runtime.
.PARAMETER WinPeSource
Optional path to a WinPE source folder containing boot.wim and bootable media files.
.PARAMETER Oa3ToolOverride
Optional override path for oa3tool.exe. When provided, takes precedence over the
embedded binary.
.PARAMETER PcpkspOverride
Optional override path for PCPKsp.dll. When provided, takes precedence over the
embedded binary.
.NOTES
  - The script embeds oa3tool.exe and PCPKsp.dll (read from the project folder at
    build time). These are Microsoft ADK binaries; redistribution is subject to
    Microsoft's license terms.
  - Formatting the USB drive erases all data on it.
  - Requires Administrator privileges.
  - A WinPE source folder is required (either manually specified or installed via
    the winget checkbox) to make the USB bootable.
  - bootsect /nt60 is used (modern bootmgr-based WinPE). /nt52 is not used as it
    is for legacy NTLDR boot and will make ADK WinPE unbootable.
  - Automatic startnet execution requires patching boot.wim; the script copies
    startnet.cmd to the USB root. The user may need to boot to WinPE and run
    Tools\Extract-AutopilotHash.ps1 manually, or patch boot.wim to launch it.
#>
[CmdletBinding()]
param(
    [string]$WinPeSource,
    [string]$Oa3ToolOverride,
    [string]$PcpkspOverride
)

# ---------------------------------------------------------------------------
# STA / Admin guard
# ---------------------------------------------------------------------------
if ([System.Threading.Thread]::CurrentThread.ApartmentState -ne 'STA') {
    throw "This script requires the STA apartment. Launch it from PowerShell Console, not ISE."
}

$identity = [System.Security.Principal.WindowsIdentity]::GetCurrent()
$principal = New-Object System.Security.Principal.WindowsPrincipal($identity)
if (-not $principal.IsInRole([System.Security.Principal.WindowsBuiltInRole]::Administrator)) {
    $ps1Path = $PSItemDefinition.FullName
    $args = "-NoProfile -ExecutionPolicy Bypass -STA -File `"$ps1Path`""
    if ($PSBoundParameters.ContainsKey('WinPeSource')) { $args += " -WinPeSource `"$WinPeSource`"" }
    if ($PSBoundParameters.ContainsKey('Oa3ToolOverride')) { $args += " -Oa3ToolOverride `"$Oa3ToolOverride`"" }
    if ($PSBoundParameters.ContainsKey('PcpkspOverride')) { $args += " -PcpkspOverride `"$PcpkspOverride`"" }
    Start-Process -FilePath powershell.exe -ArgumentList $args -Verb RunAs -Wait
    exit
}

# ---------------------------------------------------------------------------
# Embedded base64 payloads
# ---------------------------------------------------------------------------
$b64Oa3Tool = ''
$b64Pcpksp  = ''
$b64Extract = ''
$b64OA3Cfg  = 'PD94bWwgdmVyc2lvbj0iMS4wIiBlbmNvZGluZz0iVVRGLTgiPz4KPENvbmZpZ3VyYXRpb24geG1sbnM9InVybjpzY2hlbWFzLW1pY3Jvc29mdC1jb206eG1sLW1zLU9BMyI+CiAgICA8UHJvcGVydHkgTmFtZT0iRGV2aWNlTW9kZWwiIC8+CiAgICA8UHJvcGVydHkgTmFtZT0iSGFyZHdhcmVIYXNoIiAvPgo8L0NvbmZpZ3VyYXRpb24+Cg=='
$b64InputXml= 'PD94bWwgdmVyc2lvbj0iMS4wIiBlbmNvZGluZz0iVVRGLTgiPz4KPElucHV0IHhtbG5zPSJ1cm46c2NoZW1hcy1taWNyb3NvZnQtY29tOnhtbC1tcy1PQTMiPgogICAgPEtleT5QTEFDRUhPTERFUjwvS2V5PgogICAgPElkPlBMQUNFSE9MREVSPC9JZD4KPC9JbnB1dD4K'
$b64Startnet= ''

if ($b64Oa3Tool -eq '' -or $b64Pcpksp -eq '') {
    throw "This script was not built from actual oa3tool.exe and PCPKsp.dll contents."
}

function ConvertFrom-Base64ToFile {
    param([string]$Base64, [string]$Destination)
    $bytes = [System.Convert]::FromBase64String($Base64)
    [System.IO.File]::WriteAllBytes($Destination, $bytes)
}

# ---------------------------------------------------------------------------
# USB drive detection (CIM preferred, WMI fallback)
# ---------------------------------------------------------------------------
function Get-RemovableDrives {
    $drives = Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=2' -ErrorAction SilentlyContinue
    if (-not $drives) {
        $drives = Get-WmiObject Win32_LogicalDisk -Filter 'DriveType=2' -ErrorAction SilentlyContinue
    }
    $out = @()
    foreach ($d in $drives) {
        $sizeGB = [math]::Round([int64]$d.Size / 1GB, 2)
        $out += [PSCustomObject]@{
            DeviceID = $d.DeviceID
            Display  = "$($d.DeviceID)  ($sizeGB GB)"
        }
    }
    return $out
}

# ---------------------------------------------------------------------------
# Background job: does all long-running work
# ---------------------------------------------------------------------------
$jobScript = {
    param(
        [string]$UsbDrive,
        [string]$WinPeSource,
        [bool]$FormatUsb,
        [bool]$InstallWinget,
        [string]$WorkingDir
    )

    function Send-Status { param([string]$m); Write-Output "STATUS|$m" }
    function Send-Progress { param([int]$v); Write-Output "PROGRESS|$v" }

    try {
        Send-Status "Preparing USB drive..."
        Send-Progress 5

        if (-not (Test-Path $UsbDrive)) {
            throw "USB drive $UsbDrive is not accessible."
        }

        # --- Optional: Install ADK PE Addon via winget ---
        if ($InstallWinget) {
            Send-Status "Installing ADK PE Addon via winget..."
            Send-Progress 10
            $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
            if (-not $winget) {
                throw "winget.exe not found. Install the Windows ADK first."
            }
            & $winget install --id Microsoft.ADKPEAddon -e --accept-package-agreements --accept-source-agreements 2>&1
            if ($LASTEXITCODE -ne 0) {
                throw "winget install failed with exit code $LASTEXITCODE."
            }

            $adkPaths = @(
                "${env:ProgramFiles(x86)}\Windows Kits\10\Assessment and Deployment Kit\Windows Preinstallation Environment\amd64\Media",
                "${env:ProgramFiles}\Windows Kits\10\Assessment and Deployment Kit\Windows Preinstallation Environment\amd64\Media"
            )
            $found = $false
            foreach ($p in $adkPaths) {
                if (Test-Path $p) {
                    $bw = Get-ChildItem -Path $p -Filter boot.wim -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
                    if ($bw) {
                        $WinPeSource = Split-Path $bw.FullName -Parent
                        Send-Status "Found WinPE source: $WinPeSource"
                        $found = $true
                        break
                    }
                }
            }
            if (-not $found) {
                throw "winget installed but no boot.wim found in ADK directories."
            }
        }

        # --- Validate WinPE source ---
        if ($WinPeSource) {
            if (-not (Test-Path $WinPeSource)) {
                throw "WinPE source folder not found: $WinPeSource"
            }
            $indicators = @('bootmgr', 'boot\BCD', 'EFI\Boot\bootx64.efi', 'sources\boot.wim')
            $hasIndicator = $false
            foreach ($ind in $indicators) {
                if (Test-Path (Join-Path $WinPeSource $ind)) { $hasIndicator = $true; break }
            }
            if (-not $hasIndicator) {
                Send-Status "Warning: WinPE source lacks expected boot files."
            }
        }

        # --- Format USB ---
        if ($FormatUsb) {
            Send-Status "Formatting $UsbDrive (FAT32)..."
            Send-Progress 20
            & "$env:SystemRoot\System32\format.com" $UsbDrive /FS:FAT32 /Q /V:AutopilotUSB /Y
            if ($LASTEXITCODE -ne 0) {
                throw "format.com failed with exit code $LASTEXITCODE."
            }
            Start-Sleep -Seconds 3
        }

        Send-Status "Preparing USB file system..."
        Send-Progress 30

        # --- Copy WinPE source ---
        if ($WinPeSource) {
            Send-Status "Copying WinPE files to USB..."
            Send-Progress 40
            Copy-Item -Path (Join-Path $WinPeSource '*') -Destination $UsbDrive -Recurse -Force -ErrorAction SilentlyContinue
            if (-not (Test-Path (Join-Path $UsbDrive 'bootmgr')) -and -not (Test-Path (Join-Path $UsbDrive 'EFI'))) {
                Send-Status "Warning: No boot files found on USB after copy."
            }
        }

        # --- Set boot sector ---
        if ($WinPeSource) {
            Send-Status "Setting boot sector..."
            Send-Progress 50
            $bootsect = Join-Path $env:SystemRoot 'System32\bootsect.exe'
            & $bootsect /nt60 $UsbDrive /force
            if ($LASTEXITCODE -ne 0) {
                throw "bootsect /nt60 failed with exit code $LASTEXITCODE."
            }
        }

        # --- Create Tools folder and copy embedded files ---
        $usbTools = Join-Path $UsbDrive 'Tools'
        New-Item -ItemType Directory -Force -Path $usbTools | Out-Null

        Send-Status "Copying tools to USB..."
        Send-Progress 60
        Copy-Item -Path (Join-Path $WorkingDir '*') -Destination $usbTools -Recurse -Force

        # --- Write startnet.cmd to USB root ---
        $startnetSrc = Join-Path $WorkingDir 'startnet.cmd'
        if (Test-Path $startnetSrc) {
            Copy-Item -Path $startnetSrc -Destination $UsbDrive -Force
        }

        Send-Status "Complete."
        Send-Progress 100

        $copiedFiles = Get-ChildItem -Path $usbTools -Recurse | Select-Object -ExpandProperty Name
        Write-Output "RESULT|success|$UsbDrive"
        if ($copiedFiles) {
            Write-Output "FILES|$($copiedFiles -join '|')"
        }
    }
    catch {
        Write-Output "RESULT|error|$($_.Exception.Message)"
    }
}

# ---------------------------------------------------------------------------
# Windows Forms GUI
# ---------------------------------------------------------------------------
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

$form = New-Object System.Windows.Forms.Form
$form.Text = "Autopilot USB Creator"
$form.Size = New-Object System.Drawing.Size(600, 500)
$form.CenterScreen = $true
$form.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedSingle
$form.MaximizeBox = $false
$form.AutoScaleMode = [System.Windows.Forms.AutoScaleMode]::Font

# Title
$lblTitle = New-Object System.Windows.Forms.Label
$lblTitle.Text = "Autopilot USB Creator"
$lblTitle.Font = New-Object System.Drawing.Font("Segoe UI", 12.0, [System.Drawing.FontStyle]::Bold)
$lblTitle.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter
$lblTitle.Location = New-Object System.Drawing.Point(0, 10)
$lblTitle.Size = New-Object System.Drawing.Size(600, 30)
$form.Controls.Add($lblTitle)

# WinPE source folder
$lblWinPe = New-Object System.Windows.Forms.Label
$lblWinPe.Text = "WinPE source folder:"
$lblWinPe.Location = New-Object System.Drawing.Point(10, 50)
$form.Controls.Add($lblWinPe)

$txtWinPe = New-Object System.Windows.Forms.TextBox
$txtWinPe.Location = New-Object System.Drawing.Point(10, 70)
$txtWinPe.Size = New-Object System.Drawing.Size(400, 23)
$form.Controls.Add($txtWinPe)

$btnBrowseWinPe = New-Object System.Windows.Forms.Button
$btnBrowseWinPe.Text = "Browse..."
$btnBrowseWinPe.Location = New-Object System.Drawing.Point(420, 70)
$btnBrowseWinPe.Size = New-Object System.Drawing.Size(80, 26)
$btnBrowseWinPe.Add_Click({
    $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
    $dlg.Description = "Select WinPE source folder"
    if ($dlg.ShowDialog($form) -eq [System.Windows.Forms.DialogResult]::OK) {
        $txtWinPe.Text = $dlg.SelectedPath
    }
})
$form.Controls.Add($btnBrowseWinPe)

# Winget checkbox
$chkWinget = New-Object System.Windows.Forms.CheckBox
$chkWinget.Text = "Install ADK PE Addon via winget"
$chkWinget.Location = New-Object System.Drawing.Point(10, 100)
$form.Controls.Add($chkWinget)

# USB drive
$lblUsb = New-Object System.Windows.Forms.Label
$lblUsb.Text = "Select USB drive:"
$lblUsb.Location = New-Object System.Drawing.Point(10, 130)
$form.Controls.Add($lblUsb)

$cmbUsb = New-Object System.Windows.Forms.ComboBox
$cmbUsb.DropDownStyle = [System.Windows.Forms.ComboBoxStyle]::DropDownList
$cmbUsb.Location = New-Object System.Drawing.Point(10, 150)
$cmbUsb.Size = New-Object System.Drawing.Size(400, 26)
$form.Controls.Add($cmbUsb)

# Format checkbox
$chkFormat = New-Object System.Windows.Forms.CheckBox
$chkFormat.Text = "Format USB drive (FAT32)"
$chkFormat.Checked = $true
$chkFormat.Location = New-Object System.Drawing.Point(10, 180)
$form.Controls.Add($chkFormat)

# Progress label
$lblProgress = New-Object System.Windows.Forms.Label
$lblProgress.Text = "Ready"
$lblProgress.Location = New-Object System.Drawing.Point(10, 220)
$form.Controls.Add($lblProgress)

# Progress bar
$pbProgress = New-Object System.Windows.Forms.ProgressBar
$pbProgress.Location = New-Object System.Drawing.Point(10, 240)
$pbProgress.Size = New-Object System.Drawing.Size(560, 25)
$pbProgress.Style = [System.Windows.Forms.ProgressBarStyle]::Continuous
$form.Controls.Add($pbProgress)

# Create button
$btnCreate = New-Object System.Windows.Forms.Button
$btnCreate.Text = "Create USB Drive"
$btnCreate.Location = New-Object System.Drawing.Point(10, 280)
$btnCreate.Size = New-Object System.Drawing.Size(250, 40)
$form.Controls.Add($btnCreate)

# Exit button
$btnExit = New-Object System.Windows.Forms.Button
$btnExit.Text = "Exit"
$btnExit.Location = New-Object System.Drawing.Point(120, 280)
$btnExit.Size = New-Object System.Drawing.Size(300, 40)
$form.Controls.Add($btnExit)

# Populate drives
$drives = Get-RemovableDrives
if ($drives) {
    foreach ($d in $drives) {
        $cmbUsb.Items.Add($d.Display)
    }
    $cmbUsb.SelectedIndex = 0
} else {
    $cmbUsb.Items.Add("No removable drives detected")
    $cmbUsb.Enabled = $false
    $btnCreate.Enabled = $false
}

# Job tracking
$job = $null
$workingDir = $null

$jobTimer = New-Object System.Windows.Forms.Timer
$jobTimer.Interval = 1000
$jobTimer.Add_Tick({
    if ($job -and ($job.State -eq 'Completed' -or $job.State -eq 'Failed')) {
        $jobTimer.Stop()
        $output = Receive-Job -Job $job -Keep
        $lastStatus = ""
        $lastProgress = -1
        $result = $null
        $files = ""

        foreach ($line in $output) {
            if ($line -like "STATUS|*") { $lastStatus = $line.Substring(7) }
            elseif ($line -like "PROGRESS|*") { $lastProgress = [int]($line.Substring(9)) }
            elseif ($line -like "RESULT|*") { $result = $line }
            elseif ($line -like "FILES|*") { $files = $line.Substring(7) }
        }

        if ($lastStatus) { $lblProgress.Text = $lastStatus }
        if ($lastProgress -ge 0) { $pbProgress.Value = [math]::Min(100, [math]::Max(0, $lastProgress)) }

        if ($result) {
            $parts = $result -split '\|'
            $status = $parts[1]
            $drive = $parts[2]

            $cmbUsb.Enabled = $true
            $chkFormat.Enabled = $true
            $chkWinget.Enabled = $true
            $btnBrowseWinPe.Enabled = $true
            $btnCreate.Enabled = $true
            $btnExit.Enabled = $true

            if ($status -eq 'success') {
                $filesMsg = if ($files) { "Files copied:`n$($files -split '\|' -join "`n")" } else { "" }
                [System.Windows.Forms.MessageBox]::Show("USB drive $drive created successfully.`n$filesMsg", "Success", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
            } else {
                $errMsg = ($result -split '\|',3)[2]
                [System.Windows.Forms.MessageBox]::Show("Operation failed:`n$errMsg", "Error", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
            }

            # Clean up temp dir
            if ($workingDir -and (Test-Path $workingDir)) {
                Remove-Item -Path $workingDir -Recurse -Force -ErrorAction SilentlyContinue
            }
            Receive-Job -Job $job | Out-Null
            Remove-Job -Job $job -Force -ErrorAction SilentlyContinue
            $job = $null
            $workingDir = $null
        }
    }
})

# Create button click
$btnCreate.Add_Click({
    $cmbUsb.Enabled = $false
    $chkFormat.Enabled = $false
    $chkWinget.Enabled = $false
    $btnBrowseWinPe.Enabled = $false
    $btnCreate.Enabled = $false
    $btnExit.Enabled = $false

    if ($cmbUsb.Items.Count -eq 0 -or $cmbUsb.Text -eq "No removable drives detected") {
        [System.Windows.Forms.MessageBox]::Show("No removable USB drives detected.", "Error", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
        $cmbUsb.Enabled = $true
        $chkFormat.Enabled = $true
        $chkWinget.Enabled = $true
        $btnBrowseWinPe.Enabled = $true
        $btnCreate.Enabled = $true
        $btnExit.Enabled = $true
        return
    }

    $usbDrive = ($cmbUsb.Text -split ' ')[0]

    if ($chkFormat.Checked) {
        $confirm = [System.Windows.Forms.MessageBox]::Show("This will erase all data on $usbDrive. Continue?", "Confirm Format", [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Warning)
        if ($confirm -ne [System.Windows.Forms.DialogResult]::Yes) {
            $cmbUsb.Enabled = $true
            $chkFormat.Enabled = $true
            $chkWinget.Enabled = $true
            $btnBrowseWinPe.Enabled = $true
            $btnCreate.Enabled = $true
            $btnExit.Enabled = $true
            return
        }
    }

    if (-not $chkWinget.Checked -and -not $txtWinPe.Text) {
        [System.Windows.Forms.MessageBox]::Show("Please specify a WinPE source folder or check 'Install ADK PE Addon via winget'.", "Error", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
        $cmbUsb.Enabled = $true
        $chkFormat.Enabled = $true
        $chkWinget.Enabled = $true
        $btnBrowseWinPe.Enabled = $true
        $btnCreate.Enabled = $true
        $btnExit.Enabled = $true
        return
    }

    $winPeSource = if ($txtWinPe.Text) { $txtWinPe.Text.TrimEnd('\') } else { $null }

    # Create temp dir and decode embedded files
    $workingDir = Join-Path $env:TEMP ("AutopilotUSB_" + [guid]::NewGuid().ToString())
    New-Item -ItemType Directory -Force -Path $workingDir | Out-Null

    ConvertFrom-Base64ToFile $b64Oa3Tool (Join-Path $workingDir 'oa3tool.exe')
    ConvertFrom-Base64ToFile $b64Pcpksp  (Join-Path $workingDir 'PCPKsp.dll')
    ConvertFrom-Base64ToFile $b64Extract (Join-Path $workingDir 'Extract-AutopilotHash.ps1')
    ConvertFrom-Base64ToFile $b64OA3Cfg  (Join-Path $workingDir 'OA3.cfg')
    ConvertFrom-Base64ToFile $b64InputXml(Join-Path $workingDir 'input.xml')
    ConvertFrom-Base64ToFile $b64Startnet(Join-Path $workingDir 'startnet.cmd')

    # Start background job
    $job = Start-Job -ScriptBlock $jobScript -ArgumentList @($usbDrive, $winPeSource, $chkFormat.Checked, $chkWinget.Checked, $workingDir)
    $jobTimer.Start()
})

# Exit button click
$btnExit.Add_Click({
    if ($job) {
        Stop-Job -Job $job -Force -ErrorAction SilentlyContinue
        Remove-Job -Job $job -Force -ErrorAction SilentlyContinue
        $job = $null
    }
    if ($workingDir -and (Test-Path $workingDir)) {
        Remove-Item -Path $workingDir -Recurse -Force -ErrorAction SilentlyContinue
    }
    $form.Close()
})

# Form closing
$form.Add_FormClosing({
    if ($job) {
        Stop-Job -Job $job -Force -ErrorAction SilentlyContinue
        Remove-Job -Job $job -Force -ErrorAction SilentlyContinue
        $job = $null
    }
    if ($workingDir -and (Test-Path $workingDir)) {
        Remove-Item -Path $workingDir -Recurse -Force -ErrorAction SilentlyContinue
    }
})

[System.Windows.Forms.Application]::Run($form)
